pub fn dump_VariationSelector15(
    out: &mut impl Write,
    path: &str,
    value: &VariationSelector15,
    base: FontData<'_>,
) -> io::Result<()> {
    let dump_args = crate::dump_support::arguments();
    if !crate::dump_support::enter(path) {
        return writeln!(out, "{path}=traversal-limit");
    }
    {
        let path = &format!("{path}.varSelector");
        let fieldValue = value.var_selector();
        writeln!(out, "{path}={}", fieldValue.to_u32())?;
    }
    {
        let path = &format!("{path}.defaultUvsOffset");
        let fieldValue = value.default_uvs_offset();
        let rawOffset = fieldValue.offset();
        writeln!(out, "{path}={}", rawOffset.to_u32())?;
    }
    {
        let path = &format!("{path}.defaultUvs");
        let target_args: [u64; 3] = [0, 0, 0];
        crate::dump_support::set_arguments(target_args);
        match value.default_uvs(base) {
            None => writeln!(out, "{path}=none")?,
            Some(resolved) => match resolved {
                Ok(table) => table.dump(out, path)?,
                Err(error) => writeln!(out, "{path}.error={}", crate::error(error))?,
            },
        }
    }
    {
        let path = &format!("{path}.nonDefaultUvsOffset");
        let fieldValue = value.non_default_uvs_offset();
        let rawOffset = fieldValue.offset();
        writeln!(out, "{path}={}", rawOffset.to_u32())?;
    }
    {
        let path = &format!("{path}.nonDefaultUvs");
        let target_args: [u64; 3] = [0, 0, 0];
        crate::dump_support::set_arguments(target_args);
        match value.non_default_uvs(base) {
            None => writeln!(out, "{path}=none")?,
            Some(resolved) => match resolved {
                Ok(table) => table.dump(out, path)?,
                Err(error) => writeln!(out, "{path}.error={}", crate::error(error))?,
            },
        }
    }
    Ok(())
}

